-- ===========================================================================
-- Row-Level Security (docs/MULTI_TENANCY.md §5, ADR-018)
-- ===========================================================================
-- app.tenant_id / app.user_id are set per transaction with set_config(..., true).
-- nullif(...) is required: once a pooled connection has seen a setting, its unset
-- value is '' (not NULL), and ''::uuid would raise instead of matching no rows.

CREATE FUNCTION app_tenant_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.tenant_id', true), '')::uuid $$;

CREATE FUNCTION app_user_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

-- Tenant isolation on every tenant-owned table.
ALTER TABLE "role" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "role" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "role"
  USING (tenant_id = app_tenant_id()) WITH CHECK (tenant_id = app_tenant_id());

ALTER TABLE "role_permission" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "role_permission" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "role_permission"
  USING (tenant_id = app_tenant_id()) WITH CHECK (tenant_id = app_tenant_id());

ALTER TABLE "tenant_membership" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenant_membership" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "tenant_membership"
  USING (tenant_id = app_tenant_id()) WITH CHECK (tenant_id = app_tenant_id());

ALTER TABLE "tenant_audit_log" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenant_audit_log" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "tenant_audit_log"
  USING (tenant_id = app_tenant_id()) WITH CHECK (tenant_id = app_tenant_id());

-- User scope (read-only): before a tenant is chosen (login, atelier switcher), a user may
-- read their own memberships across tenants, and the roles those memberships point to.
CREATE POLICY user_own_memberships ON "tenant_membership" FOR SELECT
  USING (user_id = app_user_id());
CREATE POLICY user_membership_roles ON "role" FOR SELECT
  USING (id IN (SELECT m.role_id FROM tenant_membership m WHERE m.user_id = app_user_id()));

-- ===========================================================================
-- Append-only audit tables (enforced for every role, including the owner)
-- ===========================================================================
CREATE FUNCTION forbid_mutation() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
  END $$;

CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON "audit_log"
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
CREATE TRIGGER tenant_audit_log_append_only BEFORE UPDATE OR DELETE ON "tenant_audit_log"
  FOR EACH ROW EXECUTE FUNCTION forbid_mutation();
-- TRUNCATE bypasses row triggers; block it with a statement trigger.
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON "audit_log"
  FOR EACH STATEMENT EXECUTE FUNCTION forbid_mutation();
CREATE TRIGGER tenant_audit_log_no_truncate BEFORE TRUNCATE ON "tenant_audit_log"
  FOR EACH STATEMENT EXECUTE FUNCTION forbid_mutation();
